-- v2 (D-11) K3 replay, Adobe ARP FF K8 (BBCC314C-...), sessions created 2026-11-18 00:00-07:00 UTC, no sampling. Same window, cohort
-- (USER_IP_AT_SESSION_CREATED LIKE '2a03:4000:6:cc79:%'), List A/B/C and LT rule as v1 07_known_case_K3_adobe_arp_k8.sql;
-- thresholds = the key's OWN v2 matrix (12_build_k3_matrix_v2.py; base sampled by window, 11_k3_adobe_key_base_sampled.sql).
WITH g(d,grp,tst,tlt) AS (SELECT * FROM VALUES (-1,'Desktop',90,5400),(-1,'Mobile',90,5400),(-1,'Linux',90,5400),(-1,'WinRDVM',90,5400),(-1,'Other',90,5400),(1,'Desktop',90,5400),(1,'Mobile',90,5400),(1,'Linux',90,5400),(1,'WinRDVM',90,5400),(1,'Other',90,5400),(3,'Desktop',198.0,11880.0),(3,'Mobile',20.0,1200.0),(3,'Linux',90,5400),(3,'WinRDVM',90,5400),(3,'Other',90,5400),(7,'Desktop',51.0,4080.0),(7,'Mobile',7.5,600.0),(7,'Linux',9.0,720.0),(7,'WinRDVM',15.0,1200.0),(7,'Other',51.0,4080.0),(15,'Desktop',14.0,1680.0),(15,'Mobile',32.0,3840.0),(15,'Linux',12.0,1440.0),(15,'WinRDVM',7.95,636.0),(15,'Other',20.0,2400.0),(31,'Desktop',22.0,2640.0),(31,'Mobile',24.0,2880.0),(31,'Linux',20.0,2400.0),(31,'WinRDVM',10.5,840.0),(31,'Other',22.0,2640.0),(63,'Desktop',34.0,6120.0),(63,'Mobile',54.0,9720.0),(63,'Linux',14.0,2520.0),(63,'WinRDVM',25.5,2040.0),(63,'Other',36.0,5400)),
s0 AS (SELECT di_dictionary_num_matched_at_session_created d, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, COALESCE(user_ip_at_session_created,'') ip, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, COALESCE(di_short_term_threshold_ratio_at_session_created,0) str, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb, IFF(di_long_term_threshold_breached_at_session_created,1,0) ltb FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='BBCC314C-4937-4CCD-B0A3-FDF0F0F7603C' AND session_last_timestamp>='2026-11-18 00:00' AND session_last_timestamp<'2026-11-18 13:00' AND session_ts>='2026-11-18 00:00' AND session_ts<'2026-11-18 07:00' AND di_dictionary_num_matched_at_session_created IS NOT NULL),
s1 AS (SELECT s0.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp, IFF(ip LIKE '2a03:4000:6:cc79:%','attack','rest') c FROM s0),
f AS (SELECT s1.*, g.tst, g.tlt, IFF(x IS NULL AND (stc>g.tst OR ltc>g.tlt),1,0) na, IFF(x IS NULL AND stc>g.tst,1,0) nst FROM s1 LEFT JOIN g ON g.d=s1.d AND g.grp=s1.grp)
SELECT c||'|'||COALESCE(d::STRING,'ALL')||'|'||COALESCE(IFF(x IS NULL,grp,'SKIP_'||x),'ALL')||'|n='||COUNT(*)||'|hi='||ROUND(100*AVG(hi),1)||'|ver='||ROUND(100*AVG(ver),1)||'|thr='||COALESCE(MAX(tst)::STRING,'-')||'/'||COALESCE(MAX(tlt)::STRING,'-')||'|stc_p10/p50/max='||PERCENTILE_DISC(0.1) WITHIN GROUP (ORDER BY stc)||'/'||MEDIAN(stc)||'/'||MAX(stc)||'|T='||SUM(stb)||'|T2='||SUM(IFF(str>=2,1,0))||'|TL='||SUM(ltb)||'|NA='||SUM(na)||'/'||COALESCE(ROUND(100*SUM(na*hi)/NULLIF(SUM(na),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(na*ver)/NULLIF(SUM(na),0),1)::STRING,'-')||'|NST='||SUM(nst)||'|T_hi='||COALESCE(ROUND(100*SUM(stb*hi)/NULLIF(SUM(stb),0),1)::STRING,'-') r
FROM f GROUP BY GROUPING SETS ((c,d,x,grp),(c)) HAVING (c='attack' AND COUNT(*)>=20) OR d IS NULL OR COUNT(*)>=100000 ORDER BY 1
;
